-- Connect to the AppDb database
CREATE USER [appuser] WITH PASSWORD = 'SecureP@ssw0rd!';
ALTER ROLE db_datareader ADD MEMBER [appuser];
ALTER ROLE db_datawriter ADD MEMBER [appuser];

-- Run as Azure AD admin in the master database
CREATE USER [ada@example.com] FROM EXTERNAL PROVIDER;
ALTER ROLE db_datareader ADD MEMBER [ada@example.com];

using Microsoft.Data.SqlClient;

var connectionString = "Server=tcp:sqlserver-demo.database.windows.net,1433;Database=AppDb;Authentication=Active Directory Interactive;Encrypt=True;";
using var conn = new SqlConnection(connectionString);
await conn.OpenAsync();
